void WebRtcSignalingMessengerAsyncWaiter::SendMessage(
    const std::string& self_id, const std::string& peer_id, LocationHintPtr location_hint, const std::string& message, bool* out_success) {
  base::RunLoop loop;
  proxy_->SendMessage(std::move(self_id),std::move(peer_id),std::move(location_hint),std::move(message),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool WebRtcSignalingMessengerAsyncWaiter::SendMessage(
    const std::string& self_id, const std::string& peer_id, LocationHintPtr location_hint, const std::string& message) {
  bool async_wait_result;
  SendMessage(std::move(self_id),std::move(peer_id),std::move(location_hint),std::move(message),&async_wait_result);
  return async_wait_result;
}

void WebRtcSignalingMessengerAsyncWaiter::StartReceivingMessages(
    const std::string& self_id, LocationHintPtr location_hint, ::mojo::PendingRemote<IncomingMessagesListener> listener, bool* out_success, ::mojo::PendingRemote<ReceiveMessagesSession>* out_session) {
  base::RunLoop loop;
  proxy_->StartReceivingMessages(std::move(self_id),std::move(location_hint),std::move(listener),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             ::mojo::PendingRemote<ReceiveMessagesSession>* out_session
,
             bool success,
             ::mojo::PendingRemote<ReceiveMessagesSession> session) {*out_success = std::move(success);*out_session = std::move(session);
            loop->Quit();
          },
          &loop,
          out_success,
          out_session));
  loop.Run();
}








